432	fn parse_cargo_spec_str(s: &str) -> DepSpec {
433	    if crate::common::is_bare_semver(s) {
434	        if let Ok(v) = Version::parse(s, VersionGrammar::SemVer) {
435	            return DepSpec::CargoBare(v);
436	        }
437	    }
438	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Cargo) {
439	        return DepSpec::Range(req, s.to_string());
440	    }
441	    DepSpec::Opaque(s.to_string())
442	}
