444	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
445	    match spec {
446	        DepSpec::CargoBare(_) => Some(DepSpec::CargoBare(target.clone())),
447	        DepSpec::Range(_, original) => {
448	            if original.contains(',') {
449	                let parts: Vec<&str> = original.split(',').collect();
450	                let mut rewritten_parts = Vec::new();
451	                for part in parts {
452	                    let part_trimmed = part.trim();
453	                    let (prefix, rest) = crate::common::split_single_operator_prefix(part_trimmed)?;
454	                    if prefix.starts_with('>')
455	                        || prefix.starts_with('=')
456	                        || prefix.starts_with('^')
457	                        || prefix.starts_with('~')
458	                    {
459	                        let rendered = format!("{prefix}{}", render_at_precision(target, rest));
460	                        rewritten_parts.push(rendered);
461	                    } else if prefix.starts_with('<') {
462	                        // Upper-bound clauses are never rewritten (the clause text
463	                        // is preserved verbatim), but we must still check whether
464	                        // the target actually falls within it. If it doesn't, the
465	                        // rewrite would silently produce an impossible constraint
466	                        // (e.g. ">=2.1.0, <2.0.0"), so decline with None. If it
467	                        // does, the upper bound clause is passed through unchanged.
468	                        let bound = Version::parse(rest, target.grammar()).ok()?;
469	                        let ordering = target.partial_compare(&bound)?;
470	                        let exceeds_bound = if prefix == "<=" {
471	                            ordering == std::cmp::Ordering::Greater
472	                        } else {
473	                            ordering != std::cmp::Ordering::Less
474	                        };
475	                        if exceeds_bound {
476	                            return None;
477	                        }
478	                        rewritten_parts.push(part_trimmed.to_string());
479	                    } else {
480	                        rewritten_parts.push(part_trimmed.to_string());
481	                    }
482	                }
483	                let rendered = rewritten_parts.join(", ");
484	                let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
485	                return Some(DepSpec::Range(req, rendered));
486	            }
487	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
488	            if rest.contains('*') {
489	                return None;
490	            }
491	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
492	            let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
493	            Some(DepSpec::Range(req, rendered))
494	        }
495	        _ => None,
496	    }
497	}
