499	fn render_at_precision(target: &Version, original_clause: &str) -> String {
500	    if original_clause.contains('-') || target.is_prerelease() {
501	        return target.render().to_string();
502	    }
503	    let parts: Vec<&str> = original_clause.split('.').collect();
504	    let maj = target.major().unwrap_or(0);
505	    let min = target.minor().unwrap_or(0);
506	    let pat = target.patch().unwrap_or(0);
507	
508	    match parts.len() {
509	        1 => format!("{maj}"),
510	        2 => format!("{maj}.{min}"),
511	        _ => format!("{maj}.{min}.{pat}"),
512	    }
513	}
