1	//! Per-ecosystem manifest read/write for callisto.
2	
3	use std::path::Path;
4	use std::sync::Arc;
5	
6	use callisto_model::{
7	    ApplyPermit, DepSpec, Ecosystem, ManifestDecl, ManifestError, ManifestFormat, ManifestRole, Version, WorkspaceKind,
8	};
9	
10	pub mod atomic;
11	
12	pub mod cargo;
13	mod common;
14	pub mod npm;
15	pub mod python;
16	
17	pub use cargo::{cargo_package_name, CargoToml, InheritedDep, WorkspaceCargoResolver, WorkspaceInheritance};
18	pub use npm::{detect_npm_workspace_kind, npm_package_name, read_napi_targets, PackageJson};
19	pub use python::{python_package_name, PyprojectToml, Requirement};
20	
21	/// Package identity extracted directly from manifest source text via
22	/// [`read_identity`], without going through the full `Manifest::open`
23	/// lifecycle (workspace-inheritance context, on-disk path resolution,
24	/// atomic-write machinery). For callers that already hold a manifest's
25	/// content as a string -- a `git show` blob, a walker's pre-read buffer --
26	/// and only need the package's name and/or where its version comes from.
27	#[derive(Clone, Debug, Default, PartialEq, Eq)]
28	pub struct ManifestIdentity {
29	    pub name: Option<String>,
30	    pub version: Option<VersionSource>,
31	}
32	
33	/// Where a manifest's version declaration comes from. Distinct from a raw
34	/// `Option<String>` so Cargo's `version.workspace = true` is a real,
35	/// distinguishable case instead of being silently collapsed into "no
36	/// version present". [`read_identity`] never resolves the inherited value
37	/// (it has no workspace context) -- callers needing the resolved version
38	/// go through `Manifest::current_version` instead.
39	#[derive(Clone, Debug, PartialEq, Eq)]
40	pub enum VersionSource {
41	    Literal(String),
42	    InheritedFromWorkspace,
43	}
44	
45	/// Extracts a package's name and version source directly from `source`,
46	/// the raw text of a manifest matching `format`. Pure and I/O-free.
47	///
48	/// Replaces hand-parsing `Cargo.toml`/`package.json`/`pyproject.toml` at
49	/// call sites that already hold manifest content as a string rather than a
50	/// path `open()` can read from disk (audit pattern B) -- e.g. a `git show`
51	/// blob, or a directory-walker's pre-read buffer.
52	///
53	/// `path` is used only to build accurate `ManifestError::Parse` locations
54	/// on a parse failure; it need not exist on disk. Only the three
55	/// canonical-identity formats ([`Ecosystem::CANONICAL`]) are supported --
56	/// any other format returns `Err(ManifestError::ReadOnlyFormat)`.
57	pub fn read_identity(format: ManifestFormat, source: &str, path: &Path) -> Result<ManifestIdentity, ManifestError> {
58	    match format {
59	        ManifestFormat::CargoToml => cargo::identity_from_source(source, path),
60	        ManifestFormat::PackageJson => npm::identity_from_source(source, path),
61	        ManifestFormat::PyprojectToml => python::identity_from_source(source, path),
62	        other => Err(ManifestError::ReadOnlyFormat {
63	            path: path.to_path_buf(),
64	            format: other,
65	            reason: "read_identity only supports the three canonical-identity manifest formats \
66	                     (Cargo.toml, package.json, pyproject.toml)",
67	        }),
68	    }
69	}
70	
71	/// The role an npm `package.json` manifest's own content declares itself to
72	/// play (e.g. a napi-rs platform package, signaled by `os`+`cpu` constraint
73	/// arrays), detected directly from the manifest's already-parsed document.
74	///
75	/// Distinct from [`ManifestRole`], which reflects the role a [`ManifestDecl`]
76	/// was *opened with* (assigned externally by the caller), not what the
77	/// manifest content itself declares. [`Manifest::npm_role`] lets a caller
78	/// holding an already-open handle (e.g. from a shared cache) recover this
79	/// without a second read of the underlying file.
80	#[derive(Clone, Debug, PartialEq, Eq)]
81	pub enum NpmRole {
82	    Platform {
83	        platform: String,
84	        arch: String,
85	        abi: Option<String>,
86	    },
87	}
88	
89	/// Trait implemented by per-ecosystem manifest editors.
90	pub trait Manifest: Send + Sync {
91	    fn path(&self) -> &Path;
92	    fn ecosystem(&self) -> Ecosystem;
93	    fn role(&self) -> ManifestRole;
94	    fn package_name(&self) -> Result<String, ManifestError>;
95	    fn current_version(&self) -> Result<Version, ManifestError>;
96	    fn write_version(&mut self, v: &Version, permit: &ApplyPermit) -> Result<(), ManifestError>;
97	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError>;
98	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = callisto_model::DependencyEntry> + '_>;
99	    fn update_dependency_spec(
100	        &mut self,
101	        name: &str,
102	        kind: callisto_model::DepKind,
103	        new: DepSpec,
104	        permit: &ApplyPermit,
105	    ) -> Result<(), ManifestError>;
106	    fn is_publishable(&self) -> bool {
107	        true
108	    }
109	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
110	        if !self.is_publishable() {
111	            return vec![callisto_model::PublishTarget::None];
112	        }
113	        match self.ecosystem() {
114	            Ecosystem::Cargo => vec![callisto_model::PublishTarget::CratesIo],
115	            Ecosystem::Npm => vec![callisto_model::PublishTarget::Npm {
116	                registry: None,
117	                access: None,
118	            }],
119	            _ => vec![callisto_model::PublishTarget::None],
120	        }
121	    }
122	    fn update_optional_dependencies(
123	        &mut self,
124	        updates: &[(String, Version)],
125	        permit: &ApplyPermit,
126	    ) -> Result<(), ManifestError>;
127	    /// The role this manifest's own content declares itself to play (see
128	    /// [`NpmRole`]). `None` for every ecosystem other than npm, and for an
129	    /// npm manifest that isn't a platform package. Overridden by
130	    /// `PackageJson`, whose implementation derives this from the document
131	    /// already parsed at `open()` time -- no second disk read required.
132	    fn npm_role(&self) -> Option<NpmRole> {
133	        None
134	    }
135	}
136	
137	/// Context passed to open() to supply workspace-wide inheritance facts.
138	pub struct OpenContext<'a> {
139	    pub workspace_root: &'a Path,
140	    pub cargo_workspace: Option<Arc<WorkspaceInheritance>>,
141	    pub npm_workspace_kind: Option<WorkspaceKind>,
142	}
143	
144	impl<'a> OpenContext<'a> {
145	    /// Builds an [`OpenContext`] rooted at `root` by resolving Cargo
146	    /// workspace inheritance (when `root/Cargo.toml` exists) and detecting
147	    /// the npm workspace kind. This is the single reusable constructor for
148	    /// the "check Cargo.toml exists, load workspace inheritance, detect npm
149	    /// workspace kind" sequence that call sites previously reimplemented
150	    /// independently (audit pattern: duplication) -- see
151	    /// `callisto-graph`'s `walk`, `lib` (`Workspace::base_versions`),
152	    /// `apply`, and `commands::version` modules.
153	    pub fn for_workspace_root(root: &'a Path) -> OpenContext<'a> {
154	        let cargo_workspace = if root.join("Cargo.toml").exists() {
155	            if let Ok(resolver) = WorkspaceCargoResolver::load(&root.join("Cargo.toml")) {
156	                resolver.inheritance().ok().map(Arc::new)
157	            } else {
158	                None
159	            }
160	        } else {
161	            None
162	        };
163	
164	        let npm_workspace_kind = detect_npm_workspace_kind(root).ok().flatten();
165	
166	        OpenContext {
167	            workspace_root: root,
168	            cargo_workspace,
169	            npm_workspace_kind,
170	        }
171	    }
172	}
173	
174	/// Test-observability counter: total number of times [`open`] has been
175	/// invoked. Production code never reads this; it exists so callers (in
176	/// particular, callers building a caching layer on top of `open()`) can
177	/// write regression tests asserting that a given manifest path is opened
178	/// (read + parsed from disk) at most once per logical operation, instead of
179	/// once per call site. See `callisto-graph`'s `manifest_cache` module.
180	static OPEN_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
181	
182	/// Resets the internal manifest-open call counter to zero. Intended for use in test setup.
183	pub fn reset_open_call_count() {
184	    OPEN_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
185	}
186	
187	/// Reads the current value of the internal manifest-open call counter.
188	pub fn open_call_count() -> usize {
189	    OPEN_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
190	}
191	
192	/// Test-observability counter: total number of times a `Manifest`
193	/// implementor's `persist` has returned `Ok`. Production code never reads
194	/// this; it exists so callers can write regression tests asserting a given
195	/// manifest path is flushed to disk at most once per logical operation.
196	/// Distinct from `OPEN_CALL_COUNT` so open-count and persist-count
197	/// assertions in the same test are independent.
198	static PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
199	
200	/// Resets the internal manifest-persist call counter to zero. Intended for use in test setup.
201	pub fn reset_persist_call_count() {
202	    PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
203	}
204	
205	/// Reads the current value of the internal manifest-persist call counter.
206	pub fn persist_call_count() -> usize {
207	    PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
208	}
209	
210	/// Increments PERSIST_CALL_COUNT by one. Called by each Manifest
211	/// implementor's persist() immediately after its own atomic_write returns
212	/// Ok; PERSIST_CALL_COUNT itself is private to this module, so this is the
213	/// only way other modules in this crate may increment it.
214	pub(crate) fn record_persist_call() {
215	    PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
216	}
217	
218	/// Opens a manifest file matching `decl.format`.
219	pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, ManifestError> {
220	    OPEN_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
221	    if decl.role == ManifestRole::Lockfile {
222	        return Err(ManifestError::ReadOnlyFormat {
223	            path: decl.path.clone(),
224	            format: decl.format,
225	            reason: "lockfiles are regenerated via subprocess (§7.6 step 9), never opened as a Manifest handle",
226	        });
227	    }
228	
229	    match decl.format {
230	        #[cfg(feature = "cargo")]
231	        ManifestFormat::CargoToml => Ok(Box::new(CargoToml::open(decl, ctx)?)),
232	        #[cfg(feature = "npm")]
233	        ManifestFormat::PackageJson => Ok(Box::new(PackageJson::open(decl, ctx)?)),
234	        #[cfg(feature = "pypi")]
235	        ManifestFormat::PyprojectToml => Ok(Box::new(PyprojectToml::open(decl, ctx)?)),
236	        other => Err(ManifestError::ReadOnlyFormat {
237	            path: decl.path.clone(),
238	            format: other,
239	            reason: "not implemented — demand-gated per §2.2",
240	        }),
241	    }
242	}
243	
244	/// Dispatches spec round-trip rewriting to the appropriate ecosystem handler.
245	pub fn round_trip(ecosystem: Ecosystem, spec: &DepSpec, target: &Version) -> Option<DepSpec> {
246	    match (ecosystem, spec) {
247	        #[cfg(feature = "cargo")]
248	        (Ecosystem::Cargo, _) => cargo::round_trip(spec, target),
249	        #[cfg(feature = "npm")]
250	        (Ecosystem::Npm, _) => npm::round_trip(spec, target),
251	        #[cfg(feature = "pypi")]
252	        (Ecosystem::Pypi, _) => python::round_trip(spec, target),
253	        _ => None,
254	    }
255	}
256	
