    fn preserves_bom_on_write_round_trip() {
        let dir = tempdir().unwrap();
        let manifest_path = dir.path().join("Cargo.toml");
        fs::write(&manifest_path, callisto_fixtures::corpus::cargo_toml_bom_sample()).unwrap();

