1	use std::collections::{BTreeMap, BTreeSet};
2	use std::fs;
3	use std::path::{Path, PathBuf};
4	
5	use callisto_manifests::{open, OpenContext, WorkspaceCargoResolver};
6	use callisto_model::{ApplyPermit, CommandError, CommandOutput, CommandRunner, LockfileRefreshResult, ManifestRole};
7	
8	use crate::cascade::DepWriteTarget;
9	use crate::error::GraphError;
10	use crate::plan::{VersionPlan, VersionWriteTarget};
11	
12	/// Options governing how a version plan is applied to the workspace.
13	#[derive(Clone, Debug, Default)]
14	pub struct ApplyOptions {
15	    /// Plumbed from `--refresh-lockfiles` but not yet consulted here;
16	    /// `ApplyOutcome::lockfile_refresh_results` is consequently always `None`.
17	    pub refresh_lockfiles: bool,
18	    /// When true (snapshot mode, §8), manifest mutations are written to disk
19	    /// but changelog prepends (step 7), changeset deletions (step 8), and
20	    /// git staging (step 11) are suppressed.
21	    pub transient: bool,
22	}
23	
24	/// The result of a successful [`apply_version_plan`] call, describing which paths were written and staged.
25	#[derive(Clone, Debug, Default)]
26	pub struct ApplyOutcome {
27	    /// Reserved for lockfile refresh results; currently always `None`.
28	    pub lockfile_refresh_results: Option<Vec<LockfileRefreshResult>>,
29	    /// Paths written and staged via `git add`, relative to the workspace root.
30	    pub staged: Vec<PathBuf>,
31	}
32	
33	#[derive(Debug, Default)]
34	pub(crate) struct ManifestWriteGroup {
35	    pub(crate) bump: Option<(usize, callisto_model::Version)>,
36	    pub(crate) rewrite_indices: Vec<usize>,
37	}
38	
39	#[derive(Debug, Default)]
40	pub(crate) struct ManifestWriteClassification {
41	    pub(crate) batched: BTreeMap<PathBuf, ManifestWriteGroup>,
42	    pub(crate) excluded: BTreeSet<PathBuf>,
43	}
44	
45	pub(crate) fn classify_manifest_writes(plan: &VersionPlan) -> ManifestWriteClassification {
46	    let mut resolver_routed: BTreeSet<PathBuf> = BTreeSet::new();
47	    for bump in &plan.bumps {
48	        for write in &bump.writes {
49	            if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
50	                resolver_routed.insert(root_manifest.clone());
51	            }
52	        }
53	    }
54	    for rewrite in &plan.rewrites {
55	        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
56	            resolver_routed.insert(root_manifest.clone());
57	        }
58	    }
59	
60	    let mut by_path: BTreeMap<PathBuf, ManifestWriteGroup> = BTreeMap::new();
61	    for (idx, bump) in plan.bumps.iter().enumerate() {
62	        for write in &bump.writes {
63	            if let VersionWriteTarget::Manifest(p) = write {
64	                by_path.entry(p.clone()).or_default().bump = Some((idx, bump.to.clone()));
65	            }
66	        }
67	    }
68	    for (idx, rewrite) in plan.rewrites.iter().enumerate() {
69	        if let DepWriteTarget::Manifest(p) = &rewrite.key.target {
70	            by_path.entry(p.clone()).or_default().rewrite_indices.push(idx);
71	        }
72	    }
73	
74	    let mut batched = BTreeMap::new();
75	    let mut excluded = BTreeSet::new();
76	    for (path, group) in by_path {
77	        if resolver_routed.contains(&path) {
78	            excluded.insert(path);
79	        } else {
80	            batched.insert(path, group);
81	        }
82	    }
83	
84	    ManifestWriteClassification { batched, excluded }
85	}
86	
87	/// Writes `plan` to disk and stages the touched paths in git.
88	///
89	/// Every side effect here is unconditional -- whether to apply at all is
90	/// the caller's decision, which is why an [`ApplyPermit`] is required
91	/// rather than a `dry_run` bool: a bool carries no guarantee any caller
92	/// actually consulted it. A dry-run caller can't obtain a permit and
93	/// simply doesn't call this function; it reports `plan` instead.
94	///
95	/// # Errors
96	///
97	/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
98	/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
99	/// - I/O errors writing changelog sections or `pre.json`.
100	pub fn apply_version_plan<R: CommandRunner>(
101	    root: &Path,
102	    plan: &VersionPlan,
103	    runner: &R,
104	    opts: &ApplyOptions,
105	    permit: &ApplyPermit,
106	) -> Result<ApplyOutcome, GraphError> {
107	    let mut outcome = ApplyOutcome::default();
108	    let mut modified_paths = Vec::new();
109	
110	    let ctx = OpenContext::for_workspace_root(root);
111	
112	    let classification = classify_manifest_writes(plan);
113	
114	    for (path, group) in &classification.batched {
115	        let fmt = callisto_model::ManifestFormat::from_path(path)?;
116	        let decl = callisto_model::ManifestDecl::new(path.clone(), ManifestRole::Canonical, fmt)?;
117	        let mut handle = open(&decl, &ctx)?;
118	        let mut mutated = false;
119	
120	        if let Some((bump_idx, target_version)) = &group.bump {
121	            let bump = &plan.bumps[*bump_idx];
122	            let current = handle.current_version()?;
123	            if current == *target_version {
124	                // Already at target — skip write, fall through to rewrites.
125	            } else if current == bump.from {
126	                handle.write_version(target_version, permit)?;
127	                mutated = true;
128	            } else {
129	                return Err(GraphError::UnexpectedManifestVersion {
130	                    path: path.clone(),
131	                    expected_from: bump.from.clone(),
132	                    expected_to: bump.to.clone(),
133	                    found: current,
134	                });
135	            }
136	        }
137	
138	        for rewrite_idx in &group.rewrite_indices {
139	            let rewrite = &plan.rewrites[*rewrite_idx];
140	            handle.update_dependency_spec(
141	                &rewrite.key.name,
142	                rewrite.key.kind.unwrap_or(callisto_model::DepKind::Runtime),
143	                rewrite.to.clone(),
144	                permit,
145	            )?;
146	            mutated = true;
147	        }
148	
149	        if mutated {
150	            handle.persist(permit)?;
151	        }
152	        modified_paths.push(path.clone());
153	    }
154	
155	    for bump in &plan.bumps {
156	        for write in &bump.writes {
157	            match write {
158	                VersionWriteTarget::Manifest(p) => {
159	                    if !classification.excluded.contains(p) {
160	                        continue;
161	                    }
162	                    let fmt = callisto_model::ManifestFormat::from_path(p)?;
163	                    let decl = callisto_model::ManifestDecl::new(p.clone(), ManifestRole::Canonical, fmt)?;
164	                    let mut handle = open(&decl, &ctx)?;
165	                    let current = handle.current_version()?;
166	                    if current == bump.to {
167	                        // Already at target — skip write but still stage so git add re-stages on retry.
168	                    } else if current == bump.from {
169	                        handle.write_version(&bump.to, permit)?;
170	                        handle.persist(permit)?;
171	                    } else {
172	                        return Err(GraphError::UnexpectedManifestVersion {
173	                            path: p.clone(),
174	                            expected_from: bump.from.clone(),
175	                            expected_to: bump.to.clone(),
176	                            found: current,
177	                        });
178	                    }
179	                    modified_paths.push(p.clone());
180	                }
181	                VersionWriteTarget::CargoWorkspacePackage { root_manifest } => {
182	                    let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
183	                    ws_res.write_version(&bump.to, permit)?;
184	                    modified_paths.push(root_manifest.clone());
185	                }
186	            }
187	        }
188	    }
189	
190	    for rewrite in &plan.rewrites {
191	        match &rewrite.key.target {
192	            DepWriteTarget::Manifest(p) => {
193	                if !classification.excluded.contains(p) {
194	                    continue;
195	                }
196	                let fmt = callisto_model::ManifestFormat::from_path(p)?;
197	                let decl = callisto_model::ManifestDecl::new(p.clone(), ManifestRole::Canonical, fmt)?;
198	                let mut handle = open(&decl, &ctx)?;
199	                handle.update_dependency_spec(
200	                    &rewrite.key.name,
201	                    rewrite.key.kind.unwrap_or(callisto_model::DepKind::Runtime),
202	                    rewrite.to.clone(),
203	                    permit,
204	                )?;
205	                handle.persist(permit)?;
206	                modified_paths.push(p.clone());
207	            }
208	            DepWriteTarget::CargoWorkspaceDependency { root_manifest } => {
209	                let mut ws_res = WorkspaceCargoResolver::load(&root.join(root_manifest))?;
210	                ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
211	                modified_paths.push(root_manifest.clone());
212	            }
213	        }
214	    }
215	
216	    for pw in &plan.platform_writes {
217	        let fmt = callisto_model::ManifestFormat::from_path(&pw.manifest)?;
218	        let decl = callisto_model::ManifestDecl::new(pw.manifest.clone(), ManifestRole::Canonical, fmt)?;
219	        let mut handle = open(&decl, &ctx)?;
220	        let current = handle.current_version()?;
221	        if current == pw.version {
222	            // Already at target — skip write, but still stage so git add re-stages on retry.
223	        } else if current == pw.from {
224	            handle.write_version(&pw.version, permit)?;
225	            handle.persist(permit)?;
226	        } else {
227	            return Err(GraphError::UnexpectedManifestVersion {
228	                path: pw.manifest.clone(),
229	                expected_from: pw.from.clone(),
230	                expected_to: pw.version.clone(),
231	                found: current,
232	            });
233	        }
234	        modified_paths.push(pw.manifest.clone());
235	    }
236	
237	    for opt in &plan.optional_dep_updates {
238	        let fmt = callisto_model::ManifestFormat::from_path(&opt.manifest)?;
239	        let decl = callisto_model::ManifestDecl::new(opt.manifest.clone(), ManifestRole::Canonical, fmt)?;
240	        let mut handle = open(&decl, &ctx)?;
241	        handle.update_optional_dependencies(&opt.updates, permit)?;
242	        handle.persist(permit)?;
243	        modified_paths.push(opt.manifest.clone());
244	    }
245	
246	    if !opts.transient {
247	        for cl in &plan.changelog_writes {
248	            let rendered = callisto_changelog::render_section(&cl.input)?;
249	            callisto_changelog::prepend(
250	                root,
251	                &cl.changelog_path,
252	                &cl.input.package.display_name(),
253	                &rendered,
254	                permit,
255	            )?;
256	            modified_paths.push(cl.changelog_path.clone());
257	        }
258	
259	        for cs_path in &plan.consumed_changesets {
260	            let full = root.join(cs_path);
261	            if full.exists() {
262	                fs::remove_file(&full).map_err(|e| {
263	                    GraphError::Command(CommandError::Io {
264	                        program: "fs".to_string(),
265	                        message: e.to_string(),
266	                    })
267	                })?;
268	            }
269	            modified_paths.push(cs_path.clone());
270	        }
271	
272	        if let Some(ref pre_state) = plan.pre_state_update {
273	            let default_dir = PathBuf::from(".changeset");
274	            let pre_dir = plan
275	                .consumed_changesets
276	                .first()
277	                .and_then(|p| p.parent())
278	                .unwrap_or(&default_dir);
279	            let rel_pre_path = pre_dir.join("pre.json");
280	            let pre_path = root.join(&rel_pre_path);
281	            let text = callisto_format::write_pre_json(pre_state);
282	            callisto_manifests::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| {
283	                GraphError::Command(CommandError::Io {
284	                    program: "fs".to_string(),
285	                    message: e.to_string(),
286	                })
287	            })?;
288	            modified_paths.push(rel_pre_path);
289	        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
290	            let pre_path = root.join(rel_pre_path);
291	            if pre_path.exists() {
292	                fs::remove_file(&pre_path).map_err(|e| {
293	                    GraphError::Command(CommandError::Io {
294	                        program: "fs".to_string(),
295	                        message: e.to_string(),
296	                    })
297	                })?;
298	                modified_paths.push(rel_pre_path.clone());
299	            }
300	        }
301	    }
302	
303	    // Collect the set of ecosystems actively involved in this plan so that
304	    // only the corresponding lockfiles are staged. Staging lockfiles whose
305	    // ecosystem was not touched can sweep up unrelated user changes.
306	    use callisto_model::Ecosystem;
307	    let active_ecosystems: std::collections::HashSet<Ecosystem> = plan
308	        .bumps
309	        .iter()
310	        .filter_map(|b| {
311	            // Prefer the ecosystem declared in the PackageId; fall back to
312	            // inferring it from write targets for Bare (unprefixed) ids.
313	            if let Some(eco) = b.package.ecosystem() {
314	                return Some(eco);
315	            }
316	            // Bare id: derive ecosystem from the write targets.
317	            for write in &b.writes {
318	                let eco = match write {
319	                    VersionWriteTarget::CargoWorkspacePackage { .. } => Ecosystem::Cargo,
320	                    VersionWriteTarget::Manifest(p) => match callisto_model::ManifestFormat::from_path(p) {
321	                        Ok(fmt) => fmt.ecosystem(),
322	                        Err(_) => continue,
323	                    },
324	                };
325	                return Some(eco);
326	            }
327	            None
328	        })
329	        .chain(
330	            plan.platform_writes
331	                .iter()
332	                .filter_map(|pw| callisto_model::ManifestFormat::from_path(&pw.manifest).ok())
333	                .map(|fmt| fmt.ecosystem()),
334	        )
335	        .chain(
336	            plan.optional_dep_updates
337	                .iter()
338	                .filter_map(|opt| callisto_model::ManifestFormat::from_path(&opt.manifest).ok())
339	                .map(|fmt| fmt.ecosystem()),
340	        )
341	        .collect();
342	
343	    // Regenerate lockfiles when the caller requested a refresh and mode is not transient.
344	    // This must run BEFORE the git-staging loop so the refreshed files are on disk when they
345	    // are picked up by the staging pass below.
346	    if !opts.transient && opts.refresh_lockfiles {
347	        let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();
348	
349	        if active_ecosystems.contains(&Ecosystem::Cargo) {
350	            let out = runner
351	                .run("cargo", &["update", "--workspace"], root)
352	                .unwrap_or_else(|e| CommandOutput {
353	                    exit_code: None,
354	                    stdout: String::new(),
355	                    stderr: e.to_string(),
356	                });
357	            refresh_results.push(LockfileRefreshResult {
358	                filename: PathBuf::from("Cargo.lock"),
359	                refresh_command: "cargo update --workspace".to_string(),
360	                success: out.success(),
361	                exit_code: out.exit_code,
362	            });
363	        }
364	
365	        if active_ecosystems.contains(&Ecosystem::Pypi) {
366	            if root.join("uv.lock").exists() {
367	                let out = runner.run("uv", &["lock"], root).unwrap_or_else(|e| CommandOutput {
368	                    exit_code: None,
369	                    stdout: String::new(),
370	                    stderr: e.to_string(),
371	                });
372	                refresh_results.push(LockfileRefreshResult {
373	                    filename: PathBuf::from("uv.lock"),
374	                    refresh_command: "uv lock".to_string(),
375	                    success: out.success(),
376	                    exit_code: out.exit_code,
377	                });
378	            } else if root.join("poetry.lock").exists() {
379	                let out = runner
380	                    .run("poetry", &["lock", "--no-update"], root)
381	                    .unwrap_or_else(|e| CommandOutput {
382	                        exit_code: None,
383	                        stdout: String::new(),
384	                        stderr: e.to_string(),
385	                    });
386	                refresh_results.push(LockfileRefreshResult {
387	                    filename: PathBuf::from("poetry.lock"),
388	                    refresh_command: "poetry lock --no-update".to_string(),
389	                    success: out.success(),
390	                    exit_code: out.exit_code,
391	                });
392	            }
393	        }
394	
395	        if !refresh_results.is_empty() {
396	            outcome.lockfile_refresh_results = Some(refresh_results);
397	        }
398	    }
399	
400	    // Map each well-known lockfile to its ecosystem, then include the file
401	    // only when that ecosystem is active and the file exists on disk.
402	    let lockfile_ecosystems: &[(&str, Ecosystem)] = &[
403	        ("Cargo.lock", Ecosystem::Cargo),
404	        ("package-lock.json", Ecosystem::Npm),
405	        ("pnpm-lock.yaml", Ecosystem::Npm),
406	        ("yarn.lock", Ecosystem::Npm),
407	        ("bun.lockb", Ecosystem::Npm),
408	        ("uv.lock", Ecosystem::Pypi),
409	        ("poetry.lock", Ecosystem::Pypi),
410	        ("pdm.lock", Ecosystem::Pypi),
411	        ("Pipfile.lock", Ecosystem::Pypi),
412	    ];
413	    for (lockfile, ecosystem) in lockfile_ecosystems {
414	        if !active_ecosystems.contains(ecosystem) {
415	            continue;
416	        }
417	        let p = PathBuf::from(lockfile);
418	        if root.join(&p).exists() && !modified_paths.contains(&p) {
419	            modified_paths.push(p);
420	        }
421	    }
422	
423	    if !opts.transient && !modified_paths.is_empty() {
424	        let (existing, deleted): (Vec<_>, Vec<_>) = modified_paths.iter().partition(|p| root.join(p).exists());
425	
426	        if !existing.is_empty() {
427	            let mut args = vec!["add", "--"];
428	            let strs: Vec<String> = existing.iter().map(|p| p.display().to_string()).collect();
429	            for s in &strs {
430	                args.push(s);
431	            }
432	            let output = runner.run("git", &args, root)?;
433	            if !output.success() {
434	                return Err(GraphError::Command(CommandError::Failed {
435	                    program: "git".to_string(),
436	                    exit_code: output.exit_code,
437	                    stderr: output.redacted_stderr(),
438	                }));
439	            }
440	        }
441	
442	        if !deleted.is_empty() {
443	            let mut args = vec!["rm", "--cached", "--ignore-unmatch", "--"];
444	            let strs: Vec<String> = deleted.iter().map(|p| p.display().to_string()).collect();
445	            for s in &strs {
446	                args.push(s);
447	            }
448	            let output = runner.run("git", &args, root)?;
449	            if !output.success() {
450	                return Err(GraphError::Command(CommandError::Failed {
451	                    program: "git".to_string(),
452	                    exit_code: output.exit_code,
453	                    stderr: output.redacted_stderr(),
454	                }));
455	            }
456	        }
457	
458	        outcome.staged = modified_paths;
459	    }
460	
461	    Ok(outcome)
462	}
